draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(0, H - 50 - 20 * Math.sin(t));
  ctx.lineTo(W, H - 50 - 20 * Math.sin(t + Math.PI));
  ctx.lineTo(W, H);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('Warmth', 10, 10 + 10 * Math.sin(t));
  ctx.restore();
}
